// Loader for the pplx-decider reference vectors: the outputs of the published
// `autojev.model` pure functions (`describe`, `options`, `decision_messages`,
// `answer`) and the readout probability math for fixed inputs, generated by
// `make_vectors.py` and copied verbatim into `Fixtures/Decision`.

import Foundation
import Testing

@testable import ProviderCore

enum DecisionReferenceVectors {
    /// The vector file parsed with the provider's own order-preserving
    /// parser, so `describe[]` values keep Python's int/float spelling.
    static func load() throws -> DecisionJSON {
        let url = try #require(Bundle.module.url(
            forResource: "pplx_decider_reference_vectors", withExtension: "json",
            subdirectory: "Fixtures/Decision"))
        var text = try String(contentsOf: url, encoding: .utf8)
        // Python's `json.dumps` writes the `nan` answer-error probability as
        // the non-RFC literal `NaN`; the strict parser refuses it. It occurs
        // exactly once and is restored by `probabilities(_:)`.
        #expect(text.components(separatedBy: "NaN").count == 2)
        text = text.replacingOccurrences(of: "NaN", with: "null")
        return try DecisionJSON.parse(Data(text.utf8))
    }

    static func question(_ value: DecisionJSON) throws -> DecisionQuestion {
        let body = DecisionJSON.object([
            .init(key: "model", value: .string("m")),
            .init(key: "state", value: .null),
            .init(key: "questions", value: .object([.init(key: "q", value: value)])),
        ])
        return try DecisionRequest.parse(Data(body.compactJSON.utf8)).questions[0].question
    }

    static func probabilities(_ value: DecisionJSON?) throws -> [Double] {
        let items = try #require(value?.array)
        return try items.map { (item: DecisionJSON) throws -> Double in
            if item == .null { return .nan }
            return try #require(item.number)
        }
    }
}

extension DecisionJSON {
    var string: String? {
        if case .string(let text) = self { return text }
        return nil
    }

    var array: [DecisionJSON]? {
        if case .array(let items) = self { return items }
        return nil
    }

    var members: [Member]? {
        if case .object(let members) = self { return members }
        return nil
    }

    var number: Double? {
        switch self {
        case .float(let value): value
        case .integer(let digits): Double(digits)
        default: nil
        }
    }
}

/// Numeric equality within `tolerance`, object member order exact.
func expectApproximatelyEqual(
    _ actual: DecisionJSON, _ expected: DecisionJSON, tolerance: Double = 1e-12,
    sourceLocation: SourceLocation = #_sourceLocation
) {
    switch (actual, expected) {
    case (.object(let lhs), .object(let rhs)):
        #expect(lhs.map(\.key) == rhs.map(\.key), sourceLocation: sourceLocation)
        for (left, right) in zip(lhs, rhs) {
            expectApproximatelyEqual(left.value, right.value, tolerance: tolerance, sourceLocation: sourceLocation)
        }
    case (.array(let lhs), .array(let rhs)):
        #expect(lhs.count == rhs.count, sourceLocation: sourceLocation)
        for (left, right) in zip(lhs, rhs) {
            expectApproximatelyEqual(left, right, tolerance: tolerance, sourceLocation: sourceLocation)
        }
    default:
        if let left = actual.number, let right = expected.number {
            #expect(abs(left - right) <= tolerance, "\(left) vs \(right)", sourceLocation: sourceLocation)
        } else {
            #expect(actual == expected, sourceLocation: sourceLocation)
        }
    }
}
